+@page "/board"
+@rendermode InteractiveServer
+@inject ITaskService TaskService
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h2 class="mb-3">Project Board</h2>
+
+@if (_error is not null)
+{
+    <div class="alert alert-danger">@_error</div>
+}
+else if (_loading)
+{
+    <div class="d-flex justify-content-center my-5">
+        <div class="spinner-border" role="status">
+            <span class="visually-hidden">Loading…</span>
+        </div>
+    </div>
+}
+else
+{
+    <!-- Stats bar -->
+    <div class="stats-bar d-flex flex-wrap gap-3 mb-3">
+        <span class="badge bg-secondary">Total: @_tasks.Count</span>
+        <span class="badge bg-primary">To Do: @GetColumn("To Do").Count</span>
+        <span class="badge bg-warning text-dark">In Progress: @GetColumn("In Progress").Count</span>
+        <span class="badge bg-success">Done: @GetColumn("Done").Count</span>
+        <span class="badge bg-danger">Overdue: @_tasks.Count(t => t.DueDate.Date < DateTime.Today)</span>
+    </div>
+
+    <!-- Search -->
+    <div class="mb-3" style="max-width:400px;">
+        <input type="text" class="form-control" placeholder="Search tasks by title…"
+               @bind="_searchText" @bind:event="oninput" />
+    </div>
+
+    <!-- Kanban columns -->
+    <div class="board-columns d-flex gap-3">
+        @foreach (var status in _statuses)
+        {
+            var columnTasks = GetColumn(status);
+            var filtered = ApplySearch(columnTasks);
+            var statusIndex = Array.IndexOf(_statuses, status);
+
+            <div class="kanban-column flex-fill">
+                <div class="column-header d-flex justify-content-between align-items-center p-2 rounded-top">
+                    <strong>@status</strong>
+                    <span class="badge bg-light text-dark">@columnTasks.Count</span>
+                </div>
+
+                <div class="column-body p-2">
+                    @foreach (var task in filtered)
+                    {
+                        <div class="task-card card mb-2">
+                            <div class="card-body p-2">
+                                <h6 class="card-title mb-1">@task.Title</h6>
+                                <p class="card-text mb-1 text-muted small">@task.Assignee</p>
+                                <div class="d-flex justify-content-between align-items-center mb-1">
+                                    <span class="badge priority-@(task.Priority.ToLowerInvariant())">@task.Priority</span>
+                                    <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
+                                </div>
+                                <div class="d-flex gap-1">
+                                    @if (statusIndex > 0)
+                                    {
+                                        <button class="btn btn-outline-secondary btn-sm"
+                                                disabled="@_moving"
+                                                @onclick="() => MoveTask(task.Id, _statuses[statusIndex - 1])">
+                                            ← Move Left
+                                        </button>
+                                    }
+                                    @if (statusIndex < _statuses.Length - 1)
+                                    {
+                                        <button class="btn btn-outline-secondary btn-sm"
+                                                disabled="@_moving"
+                                                @onclick="() => MoveTask(task.Id, _statuses[statusIndex + 1])">
+                                            Move Right →
+                                        </button>
+                                    }
+                                </div>
+                            </div>
+                        </div>
+                    }
+
+                    @if (_addingToColumn == status)
+                    {
+                        <div class="card mb-2">
+                            <div class="card-body p-2">
+                                <input type="text" class="form-control form-control-sm mb-1"
+                                       placeholder="Title" @bind="_newTitle" />
+                                <input type="text" class="form-control form-control-sm mb-1"
+                                       placeholder="Assignee" @bind="_newAssignee" />
+                                <select class="form-select form-select-sm mb-1" @bind="_newPriority">
+                                    <option value="High">High</option>
+                                    <option value="Medium">Medium</option>
+                                    <option value="Low">Low</option>
+                                </select>
+                                <input type="date" class="form-control form-control-sm mb-1"
+                                       @bind="_newDueDate" />
+                                <div class="d-flex gap-1">
+                                    <button class="btn btn-primary btn-sm" disabled="@_saving"
+                                            @onclick="SaveNewTask">Save</button>
+                                    <button class="btn btn-outline-secondary btn-sm"
+                                            @onclick="CancelAdd">Cancel</button>
+                                </div>
+                            </div>
+                        </div>
+                    }
+
+                    @if (_addingToColumn != status)
+                    {
+                        <button class="btn btn-outline-primary btn-sm w-100"
+                                @onclick="() => BeginAdd(status)">
+                            + Add Task
+                        </button>
+                    }
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private readonly string[] _statuses = { "To Do", "In Progress", "Done" };
+
+    private List<TaskItem> _tasks = new();
+    private bool _loading = true;
+    private string? _error;
+    private string _searchText = string.Empty;
+
+    // Moving state
+    private bool _moving;
+
+    // Add-task form state
+    private string? _addingToColumn;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = "Medium";
+    private DateTime _newDueDate = DateTime.Today.AddDays(7);
+    private bool _saving;
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            _tasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to load tasks: {ex.Message}";
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private List<TaskItem> GetColumn(string status) =>
+        _tasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> ApplySearch(List<TaskItem> items)
+    {
+        if (string.IsNullOrWhiteSpace(_searchText))
+            return items;
+        return items.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)).ToList();
+    }
+
+    private async Task MoveTask(int taskId, string newStatus)
+    {
+        _moving = true;
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = _tasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                var old = _tasks[idx];
+                _tasks[idx] = old with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to move task: {ex.Message}";
+        }
+        finally
+        {
+            _moving = false;
+        }
+    }
+
+    private void BeginAdd(string status)
+    {
+        _addingToColumn = status;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd() => _addingToColumn = null;
+
+    private async Task SaveNewTask()
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle) || _addingToColumn is null)
+            return;
+
+        _saving = true;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
+            // CreateTaskAsync returns the task with its default status; update to target column if needed
+            if (created.Status != _addingToColumn)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, _addingToColumn);
+                created = created with { Status = _addingToColumn };
+            }
+            _tasks.Add(created);
+            _addingToColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to create task: {ex.Message}";
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
